// ---- relocatability, enforced: the wire is a pure length-prefixed
// stream AND the decoded storage is pointer-free — every closure type
// must stay trivially copyable and standard-layout, so instances can be
// memcpy'd, mmap'd, shared across processes, and walked through
// descriptor offsets. A failure here means a pointer, virtual or
// non-trivial member crept into generated storage.
static_assert( std::is_trivially_copyable<RenderCamera>::value, "RenderCamera must stay relocatable" );
static_assert( std::is_standard_layout<RenderCamera>::value, "RenderCamera must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<RenderShip>::value, "RenderShip must stay relocatable" );
static_assert( std::is_standard_layout<RenderShip>::value, "RenderShip must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<RenderTurret>::value, "RenderTurret must stay relocatable" );
static_assert( std::is_standard_layout<RenderTurret>::value, "RenderTurret must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<RenderMissile>::value, "RenderMissile must stay relocatable" );
static_assert( std::is_standard_layout<RenderMissile>::value, "RenderMissile must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<RenderDynamicProp>::value, "RenderDynamicProp must stay relocatable" );
static_assert( std::is_standard_layout<RenderDynamicProp>::value, "RenderDynamicProp must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<RenderStaticProp>::value, "RenderStaticProp must stay relocatable" );
static_assert( std::is_standard_layout<RenderStaticProp>::value, "RenderStaticProp must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<RenderCosmeticProp>::value, "RenderCosmeticProp must stay relocatable" );
static_assert( std::is_standard_layout<RenderCosmeticProp>::value, "RenderCosmeticProp must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<RenderLaser>::value, "RenderLaser must stay relocatable" );
static_assert( std::is_standard_layout<RenderLaser>::value, "RenderLaser must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<RenderExplosion>::value, "RenderExplosion must stay relocatable" );
static_assert( std::is_standard_layout<RenderExplosion>::value, "RenderExplosion must stay standard-layout for offsetof" );
static_assert( std::is_trivially_copyable<RenderFrame>::value, "RenderFrame must stay relocatable" );
